from collections import deque

class Solution:
    def hungryStudents(self, prefers: List[int], trays: List[int]) -> int:
        q = deque(prefers)
        top = passes = 0
        while q and passes < len(q):
            s = q.popleft()
            if s == trays[top]:
                top += 1
                passes = 0
            else:
                q.append(s)
                passes += 1
        return len(q)

