class Solution {
    public int hungryStudents(int[] prefers, int[] trays) {
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int p : prefers) q.add(p);
        int top = 0, passes = 0;
        while (!q.isEmpty() && passes < q.size()) {
            int s = q.poll();
            if (s == trays[top]) { top++; passes = 0; }
            else { q.add(s); passes++; }
        }
        return q.size();
    }
}

