class Solution {
public:
    int hungryStudents(vector<int>& prefers, vector<int>& trays) {
        deque<int> q(prefers.begin(), prefers.end());
        int top = 0, passes = 0;
        while (!q.empty() && passes < (int) q.size()) {
            int s = q.front();
            q.pop_front();
            if (s == trays[top]) { top++; passes = 0; }
            else { q.push_back(s); passes++; }
        }
        return q.size();
    }
};

