int hungryStudents(int* prefers, int prefersSize, int* trays, int traysSize) {
    int n = prefersSize;
    int* q = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) q[i] = prefers[i];
    int head = 0, size = n, top = 0, passes = 0;
    while (size > 0 && passes < size) {
        int s = q[head];
        head = (head + 1) % n;
        size--;
        if (s == trays[top]) { top++; passes = 0; }
        else { q[(head + size) % n] = s; size++; passes++; }
    }
    free(q);
    return size;
}

