class Solution {
    public int hungryStudents(int[] prefers, int[] trays) {
        int[] want = new int[2];
        for (int p : prefers) want[p]++;
        for (int t : trays) {
            if (want[t] == 0) break;
            want[t]--;
        }
        return want[0] + want[1];
    }
}

